void status_req_speed(void * arg)
{
	UInt8 data[2]  = {SET_SPEED, 0xFF};

#if STATUS_SPEED_ENABLE == 1
  	
      	data[1] = status_get_speed (STATUS_SPEED_BYTE) ;
    
#endif
  	d2d_tx_frame (&data[0] , sizeof_array(data)) ; 
}

